import morfologik.fsa.*;import morfologik.fsa.builders.*;import java.nio.file.*;import java.nio.charset.*;import java.util.*;import java.io.*;
public class CompileFrenchDictionary{public static void main(String[]args)throws Exception{List<byte[]>words=new ArrayList<>();for(String w:Files.readAllLines(Path.of(args[0]),StandardCharsets.UTF_8))words.add(w.getBytes(StandardCharsets.UTF_8));words.sort(FSABuilder.LEXICAL_ORDERING);FSA fsa=FSABuilder.build(words);try(OutputStream o=Files.newOutputStream(Path.of(args[1]))){new CFSA2Serializer().serialize(fsa,o);}System.out.println(words.size()+" forms; "+Files.size(Path.of(args[1]))+" bytes");}}
